<script setup lang="ts">
import { ref, watch, onMounted, onUnmounted, computed, nextTick } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import Button from 'primevue/button'; import Toast from 'primevue/toast'; import Dialog from 'primevue/dialog'; import Select from 'primevue/select'; import InputText from 'primevue/inputtext'; import Popover from 'primevue/popover'; import ConfirmDialog from 'primevue/confirmdialog';
import { useToast } from 'primevue/usetoast';
import { HubConnectionBuilder, type HubConnection } from '@microsoft/signalr';
import { api, currentUser, login, logout, accessToken } from './lib/api';
import { canAccess, homeFor } from './lib/access';
import { roleNames, initials, date, type Data, type User } from './lib/types';
const compactScreen = window.matchMedia('(max-width: 767px)'), isCompact = ref(compactScreen.matches);
const route = useRoute(), router = useRouter(), toast = useToast();
const accounts = ref<User[]>([]), chosen = ref('staff-OperationsAdmin'), signing = ref(false), loginError = ref(''), mobileMenu = ref(false), switcher = ref(false), search = ref(''), notifications = ref<Data[]>([]), popover = ref(), connected = ref(false), config = ref<Data>(); let hub: HubConnection | undefined;
const staff = computed(() => currentUser.value && !['Customer', 'Driver'].includes(currentUser.value.role));
const sections = [ { title: 'KHÔNG GIAN LÀM VIỆC', items: [ { path: '/', label: 'Tổng quan', icon: 'pi-th-large' }, { path: '/dispatch', label: 'Điều phối trực tiếp', icon: 'pi-map' }, { path: '/rides', label: 'Quản lý chuyến xe', icon: 'pi-directions-alt' } ] }, { title: 'QUẢN LÝ NỀN TẢNG', items: [ { path: '/drivers', label: 'Đối tác tài xế', icon: 'pi-id-card' }, { path: '/customers', label: 'Khách hàng', icon: 'pi-users' }, { path: '/pricing', label: 'Giá cước & vùng dịch vụ', icon: 'pi-sliders-h' }, { path: '/finance', label: 'Tài chính & đối soát', icon: 'pi-wallet' } ] }, { title: 'VẬN HÀNH & HỖ TRỢ', items: [ { path: '/support', label: 'Trung tâm hỗ trợ', icon: 'pi-headphones' }, { path: '/audit', label: 'Nhật ký hoạt động', icon: 'pi-history' }, { path: '/settings', label: 'Cấu hình hệ thống', icon: 'pi-cog' } ] } ];
const visibleSections = computed(() => sections.map(section => ({ ...section, items: section.items.filter(item => canAccess(item.path, currentUser.value?.role)) })).filter(section => section.items.length));
const canSearch = computed(() => canAccess('/rides', currentUser.value?.role));
function updateScreen() { isCompact.value = compactScreen.matches; if (!isCompact.value) mobileMenu.value = false; }
function handleMenuKeys(event: KeyboardEvent) {
  if (!mobileMenu.value) return;
  if (event.key === 'Escape') { mobileMenu.value = false; return; }
  if (event.key !== 'Tab') return;
  const items = Array.from(document.querySelectorAll<HTMLElement>('#main-sidebar a, #main-sidebar button')).filter(el => el.getClientRects().length);
  const first = items[0], last = items[items.length - 1];
  if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
}
watch(mobileMenu, async open => {
  await nextTick();
  if (open) document.querySelector<HTMLElement>('#main-sidebar .nav-item')?.focus();
  else if (isCompact.value) document.querySelector<HTMLElement>('.menu-toggle')?.focus();
});
async function openAccount() { mobileMenu.value = false; await nextTick(); if (accounts.value.length) switcher.value = true; else await logout(); }
async function signIn() { signing.value = true; loginError.value = ''; try { if (currentUser.value) await logout(); await login(chosen.value); switcher.value = false; await router.push(homeFor(currentUser.value?.role)); } catch (e) { loginError.value = (e as Error).message; } finally { signing.value = false; } }
async function loadNotifications() { const userId = currentUser.value?.id; if (userId) try { const result = await api('/notifications'); if (currentUser.value?.id === userId) notifications.value = result.items; } catch { /* Session recovery is handled by api. */ } }
async function connect() { await hub?.stop(); connected.value = false; if (!currentUser.value) return; hub = new HubConnectionBuilder().withUrl('/hubs/rides', { accessTokenFactory: accessToken }).withAutomaticReconnect().build(); hub.onreconnecting(() => { connected.value = false; }); hub.onreconnected(() => { connected.value = true; window.dispatchEvent(new Event('grap:refresh')); }); for (const event of ['ride.status.changed', 'driver.offer.created', 'payment.status.changed']) hub.on(event, () => { window.dispatchEvent(new Event('grap:refresh')); void loadNotifications(); }); try { await hub.start(); connected.value = true; } catch { connected.value = false; } }
watch(() => currentUser.value?.id, () => { notifications.value = []; search.value = ''; mobileMenu.value = false; popover.value?.hide(); void connect(); void loadNotifications(); }); watch(() => route.path, () => { mobileMenu.value = false; });
onMounted(async () => { compactScreen.addEventListener('change', updateScreen); window.addEventListener('keydown', handleMenuKeys); try { config.value = await api('/app-config'); if (config.value?.environment === 'Development') accounts.value = await api<User[]>('/auth/development/accounts'); } catch (e) { loginError.value = (e as Error).message; } void connect(); void loadNotifications(); }); onUnmounted(() => { compactScreen.removeEventListener('change', updateScreen); window.removeEventListener('keydown', handleMenuKeys); void hub?.stop(); });
async function readNotice(n: Data) { try { await api('/notifications/' + n.id + '/read', { method: 'POST' }); n.readAt = new Date().toISOString(); if (n.entityId && n.kind === 'ride') await router.push({ path: currentUser.value?.role === 'Customer' ? '/customer' : currentUser.value?.role === 'Driver' ? '/driver' : '/rides', query: { id: n.entityId } }); else if (n.kind === 'application' && canAccess('/drivers', currentUser.value?.role)) await router.push('/drivers'); popover.value?.hide(); } catch (e) { toast.add({ severity: 'error', summary: (e as Error).message }); } }
function doSearch() { if (search.value.trim()) void router.push({ path: '/rides', query: { q: search.value.trim() } }); }
</script>
<template>
 <Toast position="top-right"/><ConfirmDialog/>
 <RouterView v-if="route.path.startsWith('/share/')"/>
 <div v-else-if="!currentUser" class="login-page">
  <div class="login-story"><div class="brand inverse"><span class="brand-mark"><i class="pi pi-directions-alt"></i></span><span>grap<span class="brand-period">.</span></span></div><div class="login-story-copy"><span class="eyebrow">MỖI CHUYẾN ĐI, MỘT KẾT NỐI</span><h1>Chuyển động<br/>cùng thành phố.</h1><p>Một không gian điều hành tập trung.<br/>Kết nối tài xế, khách hàng và những hành trình an toàn.</p><div class="login-orbit"><span class="orbit-ring ring-one"></span><span class="orbit-ring ring-two"></span><span class="orbit-ring ring-three"></span><div class="orbit-center"><i class="pi pi-directions"></i></div><span class="orbit-pin pin-one"><i class="pi pi-map-marker"></i></span><span class="orbit-pin pin-two"><i class="pi pi-car"></i></span><span class="orbit-pin pin-three"><i class="pi pi-users"></i></span><div class="orbit-trip"><span class="green-dot"></span> Kết nối những hành trình mới</div></div></div><div class="login-foot">GRAP SOLUTION <span>Nền tảng di chuyển thông minh</span></div></div>
  <div class="login-form-wrap"><div class="login-form"><span class="mini-label"><i class="pi pi-shield"></i> TRUNG TÂM VẬN HÀNH</span><h2>Chào mừng trở lại<span class="green-text">.</span></h2><p class="muted">Đăng nhập để bắt đầu quản lý những hành trình.</p><div v-if="accounts.length" class="dev-login"><div class="info-box"><i class="pi pi-code"></i><div><strong>Môi trường phát triển</strong><p>Tài khoản mẫu giúp kiểm tra từng vai trò. Dữ liệu minh họa được lưu tại backend local.</p></div></div><label for="account">Chọn tài khoản trải nghiệm</label><Select input-id="account" v-model="chosen" :options="accounts" option-value="id" :option-label="(a: User) => `${a.name} · ${roleNames[a.role]}`" filter class="full-width"/><p v-if="loginError" class="form-error" role="alert">{{ loginError }}</p><Button label="Vào không gian làm việc" icon="pi pi-arrow-right" icon-pos="right" :loading="signing" @click="signIn" class="full-width login-button"/><div class="login-role-hints"><span><i class="pi pi-check-circle"></i> Phân quyền theo vai trò</span><span><i class="pi pi-check-circle"></i> Dữ liệu lưu bền vững</span></div></div><div v-else class="info-box"><i class="pi pi-info-circle"></i><p>{{ loginError || 'Đăng nhập nhân sự production cần được tích hợp OIDC/MFA trước khi mở vận hành.' }}</p></div><p class="login-policy">Hệ thống dành cho nhân sự và đối tác được cấp quyền.<br/>Mọi thao tác nghiệp vụ được ghi nhận để truy vết.</p></div><span class="login-copyright">© 2026 Grap Solution · Made for better journeys</span></div>
 </div>
 <div v-else class="app-shell"><a class="skip-link" href="#main-content">Đến nội dung chính</a>
  <div v-if="mobileMenu" class="sidebar-backdrop" @click="mobileMenu = false"></div>
  <aside id="main-sidebar" :inert="isCompact && !mobileMenu" class="sidebar" :class="{ open: mobileMenu }"><RouterLink :to="homeFor(currentUser.role)" class="brand"><span class="brand-mark"><i class="pi pi-directions-alt"></i></span><span>grap<span class="brand-period">.</span></span><span class="brand-console">CONSOLE</span></RouterLink><div class="workspace-picker"><span class="workspace-icon"><i class="pi pi-building"></i></span><div><strong>Grap Solution</strong><span>Không gian vận hành</span></div><i class="pi pi-verified green-text"></i></div><nav v-if="staff"><div v-for="section in visibleSections" :key="section.title" class="nav-section"><span class="nav-section-label">{{ section.title }}</span><RouterLink v-for="item in section.items" :key="item.path" :to="item.path" @click="mobileMenu=false" class="nav-item" :class="{ active: route.path === item.path }" :aria-current="route.path === item.path ? 'page' : undefined"><i class="pi" :class="item.icon"></i><span>{{ item.label }}</span><span v-if="item.path === '/dispatch'" class="nav-live"></span></RouterLink></div></nav><nav v-else class="nav-section"><span class="nav-section-label">ỨNG DỤNG TRẢI NGHIỆM</span><RouterLink :to="currentUser.role === 'Driver' ? '/driver' : '/customer'" class="nav-item active" @click="mobileMenu=false"><i class="pi pi-map"></i>{{ currentUser.role === 'Driver' ? 'Không gian tài xế' : 'Đặt chuyến xe' }}</RouterLink></nav><div class="sidebar-bottom"><div class="sidebar-help"><span class="help-icon"><i class="pi pi-sparkles"></i></span><strong>Cùng vận hành tốt hơn</strong><p>Mỗi hành trình an toàn bắt đầu từ sự tận tâm của bạn.</p><RouterLink v-if="canAccess('/support', currentUser.role)" to="/support">Trung tâm hỗ trợ <i class="pi pi-arrow-up-right"></i></RouterLink></div><button class="user-card" @click="openAccount"><span class="avatar mint">{{ initials(currentUser.name) }}</span><span class="user-card-text"><strong>{{ currentUser.name }}</strong><small>{{ roleNames[currentUser.role] }}</small></span><i class="pi pi-ellipsis-v"></i></button></div><button v-if="isCompact" class="icon-button sidebar-close" aria-label="Đóng menu" @click="mobileMenu=false"><i class="pi pi-times"></i></button></aside>
  <div class="main-shell" :inert="isCompact && mobileMenu"><header class="topbar"><div class="breadcrumb"><button class="icon-button menu-toggle" aria-label="Mở menu" :aria-expanded="mobileMenu" aria-controls="main-sidebar" @click="mobileMenu = !mobileMenu"><i class="pi pi-bars"></i></button><i class="pi pi-home"></i><i class="pi pi-angle-right separator"></i><span>{{ route.meta.title }}</span></div><div class="topbar-actions"><form v-if="canSearch" class="global-search" @submit.prevent="doSearch"><i class="pi pi-search"></i><input v-model="search" placeholder="Tìm mã chuyến xe…" aria-label="Tìm mã chuyến xe"/><kbd>↵</kbd></form><span class="connection" :class="{ disconnected: !connected }"><span></span>{{ connected ? 'Đã kết nối' : 'Đang kết nối lại' }}</span><button class="icon-button notification-button" aria-label="Thông báo" @click="popover.toggle($event); loadNotifications()"><i class="pi pi-bell"></i><span v-if="notifications.some(n => !n.readAt)" class="notification-dot"></span></button><div class="topbar-divider"></div><span class="avatar small mint">{{ initials(currentUser.name) }}</span></div></header><main id="main-content" class="page-content" tabindex="-1"><RouterView v-slot="{ Component }"><component :is="Component" :key="route.path + currentUser.id"/></RouterView><footer class="page-footer"><span>© 2026 Grap Solution</span><span><i class="pi pi-circle-fill"></i> {{ config?.environment === 'Development' ? 'Môi trường phát triển · Dữ liệu mẫu' : 'Trung tâm vận hành' }} <b>v0.1.0</b></span></footer></main></div>
 </div>
 <Popover ref="popover"><div class="notifications-panel"><h3>Thông báo <span class="muted">{{ notifications.filter(n => !n.readAt).length }} chưa đọc</span></h3><p v-if="!notifications.length" class="muted">Bạn đã xem hết thông báo.</p><button v-for="n in notifications.slice(0, 12)" :key="n.id" class="notification-row" :class="{ unread: !n.readAt }" @click="readNotice(n)"><i class="pi pi-directions-alt"></i><span><strong>{{ n.title }}</strong><small>{{ n.body }}</small><small>{{ date(n.createdAt) }}</small></span></button></div></Popover>
 <Dialog v-model:visible="switcher" modal header="Tài khoản & vai trò" :style="{ width: '480px' }"><p class="muted">Chuyển vai trò trong môi trường phát triển để kiểm tra quyền nghiệp vụ.</p><Select v-model="chosen" :options="accounts" option-value="id" :option-label="(a: User) => `${a.name} · ${roleNames[a.role]}`" filter class="full-width"/><p v-if="loginError" class="form-error">{{ loginError }}</p><template #footer><Button label="Đăng xuất" severity="secondary" text @click="logout(); switcher = false"/><Button label="Chuyển tài khoản" :loading="signing" @click="signIn"/></template></Dialog>
</template>
